import { Component, Inject } from '@angular/core';
import { FormControl, FormGroup } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import {
    AsyncHandler,
    getInvalidFields,
    notifyError,
    notifySuccess,
    uploadFile,
} from '@placeos/common';
import {
    addSettings,
    EncryptionLevel,
    PlaceSettings,
    PlaceZone,
    querySettings,
    updateSettings,
} from '@placeos/ts-client';
import { of } from 'rxjs';
import { catchError, map } from 'rxjs/operators';

import * as yaml from 'js-yaml';
import { validateURL } from '@placeos/spaces';

@Component({
    selector: `booking-panel-settings-modal`,
    template: `
        <div class="w-screen h-screen bg-base-100 flex flex-col overflow-auto">
            <header
                class="sticky top-0 px-4 py-2 mx-auto my-2 max-w-[640px] w-full border-none z-10 bg-base-200 rounded"
            >
                <h2 class="text-xl font-medium">
                    Booking Panel Settings - {{ zone.display_name }}
                </h2>
                <button icon matRipple mat-dialog-close *ngIf="!loading">
                    <app-icon>close</app-icon>
                </button>
            </header>
            <main
                class="h-1/2 flex-1 p-4 space-y-8 z-0 max-w-[640px] w-full mx-auto"
            >
                <form
                    [formGroup]="form"
                    class="flex flex-col space-y-4"
                    *ngIf="!loading; else load_state"
                >
                    <div
                        class="relative flex flex-col p-2 border border-base-300 rounded mb-4"
                    >
                        <h4
                            class="absolute top-0 left-8 -translate-y-1/2 bg-base-100 text-sm p-2"
                        >
                            Booking Settings
                        </h4>
                        <div class="flex items-center flex-wrap -mx-2">
                            <settings-toggle
                                name="Disable booking"
                                formControlName="disable_book_now"
                            ></settings-toggle>
                            <settings-toggle
                                name="Hide booking host options"
                                formControlName="disable_book_now_host"
                            ></settings-toggle>
                        </div>
                        <div class="flex space-x-4">
                            <div class="flex-1 h-20">
                                <label for="min-duration"
                                    >Minimum Booking Duration</label
                                >
                                <a-duration-field
                                    name="min-duration"
                                    formControlName="min_duration"
                                    [min]="0"
                                    [step]="
                                        form.value.max_duration > 60 ? 15 : 5
                                    "
                                    [max]="form.value.max_duration"
                                ></a-duration-field>
                            </div>
                            <div class="flex-1 h-20">
                                <label for="max-duration"
                                    >Maximum Booking Duration</label
                                >
                                <a-duration-field
                                    name="max-duration"
                                    formControlName="max_duration"
                                    [min]="
                                        form.value.min_duration +
                                        15 -
                                        (form.value.min_duration % 15)
                                    "
                                    [step]="15"
                                    [max]="480"
                                ></a-duration-field>
                            </div>
                        </div>
                    </div>
                    <div class="flex space-x-4">
                        <div class="flex-1">
                            <label for="pending_before"
                                >Allow check-in before meeting</label
                            >
                            <a-duration-field
                                name="pending_before"
                                formControlName="pending_before"
                                [min]="0"
                                [step]="5"
                                [max]="60"
                            ></a-duration-field>
                        </div>
                        <div class="flex-1">
                            <label for="pending_period"
                                >Cancel not checked-in meetings after</label
                            >
                            <a-duration-field
                                name="pending_period"
                                formControlName="pending_period"
                                [min]="0"
                                [step]="5"
                                [max]="60"
                            ></a-duration-field>
                        </div>
                    </div>
                    <div class="flex items-center flex-wrap -mx-2">
                        <settings-toggle
                            name="Disable auto-ending bookings"
                            formControlName="disable_end_meeting"
                            info="Disable ending the current booking early when sensors
don't detect presence in room after a period of time"
                        ></settings-toggle>
                        <settings-toggle
                            name="Show button to end booking early"
                            formControlName="enable_end_meeting_button"
                        ></settings-toggle>
                        <settings-toggle
                            name="Hide Meeting Details"
                            formControlName="hide_meeting_details"
                            info="When enabled only shows the time of the current meeting"
                        ></settings-toggle>
                        <settings-toggle
                            name="Hide Meeting Title"
                            formControlName="hide_meeting_title"
                            info="When enabled only shows the time and host of the current meeting"
                        ></settings-toggle>
                        <settings-toggle
                            name="Show Booking QR Code"
                            formControlName="show_qr_code"
                        ></settings-toggle>
                    </div>
                    <div class="mb-2">
                        <label for="custom-qr-url">Custom QR Code URL</label>
                        <mat-form-field appearance="outline" class="w-full">
                            <input
                                matInput
                                name="custom-qr-url"
                                placeholder="/workplace/#/book/room/?room_id=sys-123456"
                                formControlName="custom_qr_url"
                            />
                            <mat-error>
                                Custom QR Code URL must be a valid URL
                            </mat-error>
                            <mat-hint>
                                Custom QR Code URL will replace the default
                                Booking QR Code
                            </mat-hint>
                        </mat-form-field>
                    </div>
                    <div class="flex space-x-4">
                        <div class="flex-1">
                            <label for="room-image">Room Image URL</label>
                            <div class="flex space-x-2">
                                <mat-form-field
                                    appearance="outline"
                                    class="w-1/2 flex-1"
                                >
                                    <input
                                        matInput
                                        name="room-image"
                                        placeholder="/assets/images/room_test1.png"
                                        formControlName="room_image"
                                    />
                                    <mat-error>
                                        Room Image must be a valid URL
                                    </mat-error>
                                </mat-form-field>
                                <button
                                    icon
                                    matRipple
                                    [disabled]="uploading"
                                    class="bg-secondary text-secondary-content rounded h-12 w-12"
                                >
                                    <app-icon>cloud_upload</app-icon>
                                    <input
                                        type="file"
                                        class="absolute inset-0 opacity-0"
                                        (change)="
                                            uploadImage($event, 'room_image')
                                        "
                                    />
                                </button>
                            </div>
                        </div>
                        <div class="flex-1">
                            <label for="offline-image">Offline Image URL</label>
                            <div class="flex space-x-2">
                                <mat-form-field
                                    appearance="outline"
                                    class="w-1/2 flex-1"
                                >
                                    <input
                                        matInput
                                        name="offline-image"
                                        placeholder="/assets/images/offline1.png"
                                        formControlName="offline_image"
                                    />
                                    <mat-error>
                                        Offline Image must be a valid URL
                                    </mat-error>
                                </mat-form-field>
                                <button
                                    icon
                                    matRipple
                                    [disabled]="uploading"
                                    class="relative bg-secondary text-secondary-content rounded h-12 w-12"
                                >
                                    <app-icon>cloud_upload</app-icon>
                                    <input
                                        type="file"
                                        class="absolute inset-0 opacity-0"
                                        (change)="
                                            uploadImage($event, 'offline_image')
                                        "
                                    />
                                </button>
                            </div>
                        </div>
                    </div>
                </form>
                <div class="h-16 w-full"></div>
            </main>
            <footer
                class="fixed bottom-0 left-1/2 -translate-x-1/2 px-4 py-2 mx-auto my-2 max-w-[640px] w-full border-none z-10 bg-base-200 rounded flex items-center justify-end"
                *ngIf="!loading"
            >
                <button btn matRipple class="w-32" (click)="save()">
                    Save
                </button>
            </footer>
        </div>
        <ng-template #load_state>
            <div
                class="w-full flex-1 h-1/2 flex flex-col items-center justify-center p-12"
            >
                <mat-spinner [diameter]="32"></mat-spinner>
                <p class="text-center">{{ loading }}</p>
            </div>
        </ng-template>
    `,
    styles: [
        `
            settings-toggle {
                width: calc(50% - 1rem);
                margin: 0.5rem;
            }
        `,
    ],
})
export class BookingPanelSettingsModalComponent extends AsyncHandler {
    public loading = '';
    public uploading = 0;
    public readonly zone = this._data.zone;
    public readonly form = new FormGroup({
        control_ui: new FormControl('', validateURL),
        catering_ui: new FormControl('', validateURL),
        custom_qr_url: new FormControl('', validateURL),
        custom_qr_color: new FormControl(''),
        show_qr_code: new FormControl(true),
        disable_book_now: new FormControl(false),
        disable_book_now_host: new FormControl(true),
        disable_end_meeting: new FormControl(false),
        enable_end_meeting_button: new FormControl(false),
        hide_meeting_details: new FormControl(false),
        hide_meeting_title: new FormControl(false),
        min_duration: new FormControl(15),
        max_duration: new FormControl(60),
        pending_before: new FormControl(5),
        pending_period: new FormControl(15),
        room_image: new FormControl('', validateURL),
        offline_image: new FormControl('', validateURL),
    });

    private _defaults: Record<string, any> = {};

    constructor(
        @Inject(MAT_DIALOG_DATA) private _data: { zone: PlaceZone },
        private _dialog_ref: MatDialogRef<BookingPanelSettingsModalComponent>,
    ) {
        super();
    }

    public async ngOnInit() {
        if (!this.zone?.id) {
            notifyError(
                'Opened booking panel settings modal with invalid zone',
            );
            return;
        }
        this.subscription(
            'max_duration',
            this.form.controls.max_duration.valueChanges.subscribe(
                (max_duration) => {
                    if (max_duration <= 60) return;
                    this.form.patchValue({
                        min_duration: Math.max(
                            15,
                            Math.floor(this.form.value.min_duration / 15) * 15,
                        ),
                    });
                },
            ),
        );
        this._defaults = { ...this.form.getRawValue() };
        this.loading = 'Loading existing panel settings...';
        const settings = await querySettings({ parent_id: this.zone.id })
            .pipe(
                catchError(() => of({ data: [] as PlaceSettings[] })),
                map((_) => _.data),
            )
            .toPromise();
        const unencrypted_settings = settings.find(
            (block) => block.encryption_level === EncryptionLevel.None,
        );
        if (!unencrypted_settings) {
            this.loading = '';
            return;
        }
        this.loading = 'Processing found panel settings...';
        const setting_value =
            yaml.load(unencrypted_settings.settings_string) || {};
        this.form.patchValue(setting_value);
        this.loading = '';
    }

    public uploadImage(event: Event, link_field: string) {
        const element: HTMLInputElement = event.target as any;
        /* istanbul ignore else */
        if (!element?.files?.length) return;
        const files: FileList = element.files;
        const file = files[0];
        const field = this.form.get(link_field);
        if (!field) return;
        if (!file.type.includes('image')) {
            return notifyError('File is not an image');
        }
        uploadFile(file).subscribe(
            (s) => {
                this.uploading = s.progress;
                if (s.link) {
                    this.uploading = 0;
                    field.setValue(s.link);
                }
            },
            () => {
                notifyError('Failed to upload image. Try again later');
                this.uploading = 0;
            },
        );
    }

    public async save() {
        this.form.markAllAsTouched();
        if (!this.form.valid) {
            return notifyError(
                `Some form fields are invalid. [${getInvalidFields(this.form)}]`,
            );
        }
        const form_value = this.form.getRawValue();
        this._dialog_ref.disableClose = true;
        this.loading = 'Loading existing booking panel settings...';
        const settings = await querySettings({ parent_id: this.zone.id })
            .pipe(
                catchError(() => of({ data: [] as PlaceSettings[] })),
                map((_) => _.data),
            )
            .toPromise();
        let unencrypted_settings = settings.find(
            (block) => block.encryption_level === EncryptionLevel.None,
        );
        if (!unencrypted_settings)
            unencrypted_settings = new PlaceSettings({
                encryption_level: EncryptionLevel.None,
            });
        const setting_value =
            yaml.load(unencrypted_settings.settings_string) || {};
        const new_settings_blob = {
            ...setting_value,
            ...form_value,
        };
        // Remove default values from settings
        // for (const key in this._defaults) {
        //     if (this._defaults[key] === new_settings_blob[key]) {
        //         delete new_settings_blob[key];
        //     }
        // }
        const new_setting = {
            ...unencrypted_settings,
            settings_string: yaml.dump(new_settings_blob),
        };
        this.loading = 'Saving changes to booking panel settings...';
        const update = unencrypted_settings.id
            ? updateSettings(unencrypted_settings.id, new_setting)
            : addSettings(new_setting);
        await update.toPromise().catch((e) => {
            this._dialog_ref.disableClose = false;
            this.loading = '';
            notifyError('Error saving changes to booking panel settings');
            throw e;
        });
        this._dialog_ref.close();
        notifySuccess(
            `Successfully updated booking panel settings for "${this.zone.display_name}"`,
        );
    }
}
